let currentModalTOList = [];

const FUNNY_ALERT_IMAGES = {
  dday: "data:image/webp;base64,",
  d1: "data:image/webp;base64,",
  d2: "data:image/webp;base64,",
  d4: "data:image/webp;base64,",
  d5: "data:image/webp;base64,",
};

const FUNNY_ALERT_CONFIG = {
  d0:    { img: FUNNY_ALERT_IMAGES.d1,   text: "Tutor Dekk??" },
  d1:    { img: FUNNY_ALERT_IMAGES.dday, text: "Mantap Sanakk" },
  d2:    { img: FUNNY_ALERT_IMAGES.d2,   text: "Ayo di cariin paket nya mas" },
  d3:    { img: FUNNY_ALERT_IMAGES.d4,   text: "Ayo kapan ini mau di keluarin paket nya?" },
  d4:    { img: FUNNY_ALERT_IMAGES.d4,   text: "Ayo kapan ini mau di keluarin paket nya?" },
  d5:    { img: FUNNY_ALERT_IMAGES.d5,   text: "Mau saya pecat kamu???" },
  d5plus: { img: FUNNY_ALERT_IMAGES.d5,  text: "Mau saya pecat kamu???" },
  d6:    { img: FUNNY_ALERT_IMAGES.d5,   text: "Mau saya pecat kamu???" },
  dMore: { img: FUNNY_ALERT_IMAGES.d5,   text: "Mau saya pecat kamu???" }
};

function triggerFunnyAlert(agingType) {
  const cfg = FUNNY_ALERT_CONFIG[agingType];
  const box = document.getElementById('funnyAlertBox');
  const img = document.getElementById('funnyAlertImg');
  const bubble = document.getElementById('funnyAlertBubble');
  if (!box || !img || !bubble) return;

  if (!cfg) {
    box.classList.add('hidden');
    return;
  }

  img.src = cfg.img;
  bubble.innerText = cfg.text;

  box.classList.remove('hidden');
  box.style.opacity = '0';
  box.style.transform = 'translateY(8px)';
  void box.offsetWidth; // force reflow
  requestAnimationFrame(() => {
    box.style.opacity = '1';
    box.style.transform = 'translateY(0)';
  });
}

function hideFunnyAlert() {
  const box = document.getElementById('funnyAlertBox');
  if (!box) return;
  box.style.opacity = '0';
  box.style.transform = 'translateY(8px)';
  box.classList.add('hidden');
}



const TO_TYPE_RANK = { HV: 0, LIQUID: 1, TTO_HUB: 2, BAG: 3, BULKY: 4, OTHER: 5 };

function classifyToType(item) {
  if (item.isHv) return 'HV';
  if (item.isLiquid) return 'LIQUID';

  const isForward = String(item.journeyType || '').trim().toLowerCase() === 'forward';
  if (!isForward) return 'OTHER'; // Return: pakai model lama (Non-HV), gak dipecah Bag/Bulky/TTO Hub

  const method = String(item.packingMethod || '').trim();
  const senderIsHub = String(item.senderName || '').toLowerCase().includes('hub');
  const receiverIsHub = String(item.receiverName || '').toLowerCase().includes('hub');

  if (senderIsHub && receiverIsHub && method === 'Individual Packing') return 'TTO_HUB';
  if (method === 'Assisted Sorting') return 'BAG';
  if (method === 'Individual Packing') return 'BULKY';
  return 'OTHER';
}

function toTypeBadgeHtml(toType) {
  switch (toType) {
    case 'HV':
      return `<span class="bg-rose-100 dark:bg-rose-950/80 text-rose-700 dark:text-rose-300 font-extrabold px-2 py-0.5 rounded-full text-[9px] border border-rose-300 dark:border-rose-800"><i class="fa-solid fa-gem mr-1"></i>HV</span>`;
    case 'LIQUID':
      return `<span class="bg-sky-100 dark:bg-sky-950/80 text-sky-700 dark:text-sky-300 font-extrabold px-2 py-0.5 rounded-full text-[9px] border border-sky-300 dark:border-sky-800"><i class="fa-solid fa-bottle-droplet mr-1"></i>Liquid</span>`;
    case 'TTO_HUB':
      return `<span class="bg-violet-100 dark:bg-violet-950/80 text-violet-700 dark:text-violet-300 font-extrabold px-2 py-0.5 rounded-full text-[9px] border border-violet-300 dark:border-violet-800"><i class="fa-solid fa-shuffle mr-1"></i>TTO Hub</span>`;
    case 'BAG':
      return `<span class="bg-amber-100 dark:bg-amber-950/80 text-amber-700 dark:text-amber-300 font-extrabold px-2 py-0.5 rounded-full text-[9px] border border-amber-300 dark:border-amber-800"><i class="fa-solid fa-sack-xmark mr-1"></i>Bag</span>`;
    case 'BULKY':
      return `<span class="bg-emerald-100 dark:bg-emerald-950/80 text-emerald-700 dark:text-emerald-300 font-extrabold px-2 py-0.5 rounded-full text-[9px] border border-emerald-300 dark:border-emerald-800"><i class="fa-solid fa-box mr-1"></i>Bulky</span>`;
    default:
      return `<span class="bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 font-semibold px-2 py-0.5 rounded-full text-[9px] border border-slate-200 dark:border-slate-700">Non-HV</span>`;
  }
}

let modalAllRows = [];
let modalSearchTerm = '';
let modalSortMode = 'oldest';

function agingLabelFromDays(n) { return n <= 0 ? 'D-Day' : 'D-' + n; }

function modalAgingTypeLabel(type) {
  return { d0: 'D-Day', d1: 'D-1', d2: 'D-2', d3: 'D-3', d4: 'D-4', d5: 'D-5', d5plus: 'D-5+', d6: 'D-6', dMore: '>D-4' }[type] || String(type).toUpperCase();
}

function agingPillClass(days) {
  if (days >= 5) return 'bg-rose-100 text-rose-700 border-rose-300 dark:bg-rose-950/70 dark:text-rose-300 dark:border-rose-800';
  if (days >= 3) return 'bg-orange-100 text-orange-700 border-orange-300 dark:bg-orange-950/70 dark:text-orange-300 dark:border-orange-800';
  if (days === 2) return 'bg-amber-100 text-amber-700 border-amber-300 dark:bg-amber-950/70 dark:text-amber-300 dark:border-amber-800';
  return 'bg-emerald-100 text-emerald-700 border-emerald-300 dark:bg-emerald-950/70 dark:text-emerald-300 dark:border-emerald-800';
}

function agingBorderClass(days) {
  if (days >= 5) return 'border-rose-500';
  if (days >= 3) return 'border-orange-400';
  if (days === 2) return 'border-amber-400';
  return 'border-transparent';
}

function modalOperatorHtml(raw) {
  if (!raw || raw === '-') return '<span class="text-slate-400">N/A</span>';
  const m = String(raw).match(/^\[([^\]]+)\]\s*(.*)$/);
  if (!m) return '<div class="font-semibold text-sm text-slate-800 dark:text-slate-100 truncate" title="' + escapeHtml(raw) + '">' + escapeHtml(raw) + '</div>';
  return '<div class="leading-tight min-w-0"><div class="font-bold text-sm text-slate-800 dark:text-slate-100 truncate" title="' + escapeHtml(m[2] || m[1]) + '">' + escapeHtml(m[2] || m[1]) +
    '</div><div class="font-mono text-xs text-slate-400 dark:text-slate-500">' + escapeHtml(m[1]) + '</div></div>';
}

function modalPackTimeHtml(raw) {
  const m = String(raw || '').match(/^(\d{4})-(\d{2})-(\d{2})\s+(\d{2}):(\d{2})/);
  if (!m) return '<span class="text-slate-400">-</span>';
  const d = new Date(+m[1], +m[2] - 1, +m[3], +m[4], +m[5]);
  const hari = ['Min', 'Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab'];
  const bulan = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agt', 'Sep', 'Okt', 'Nov', 'Des'];
  const now = new Date();
  const dayDiff = Math.round((new Date(now.getFullYear(), now.getMonth(), now.getDate()) - new Date(d.getFullYear(), d.getMonth(), d.getDate())) / 86400000);
  const dayLabel = dayDiff <= 0 ? 'Hari ini' : dayDiff === 1 ? 'Kemarin' : dayDiff + ' hari lalu';
  const mins = Math.max(0, Math.floor((now - d) / 60000));
  const ago = mins < 60 ? mins + ' menit lalu'
    : mins < 1440 ? Math.floor(mins / 60) + ' jam lalu'
    : Math.floor(mins / 1440) + ' hari' + (Math.floor((mins % 1440) / 60) ? ' ' + Math.floor((mins % 1440) / 60) + ' jam' : '') + ' lalu';
  const tone = dayDiff <= 0 ? 'text-emerald-600 dark:text-emerald-400'
    : dayDiff === 1 ? 'text-amber-600 dark:text-amber-400'
    : 'text-red-600 dark:text-red-400';
  return '<div class="leading-tight">' +
    '<div class="text-base font-extrabold font-mono text-slate-800 dark:text-slate-100"><i class="fa-regular fa-clock text-slate-400 text-xs mr-1"></i>' + m[4] + ':' + m[5] + '</div>' +
    '<div class="text-xs font-semibold text-slate-600 dark:text-slate-300 mt-0.5">' + hari[d.getDay()] + ', ' + d.getDate() + ' ' + bulan[d.getMonth()] + ' ' + d.getFullYear() + '</div>' +
    '<div class="text-[11px] font-bold ' + tone + ' mt-0.5">' + (dayDiff >= 2 ? ago : dayLabel + ' &middot; ' + ago) + '</div>' +
    '</div>';
}

function getModalVisibleRows() {
  const q = modalSearchTerm.trim().toLowerCase();
  let rows = q
    ? modalAllRows.filter(r => String(r.toNo).toLowerCase().includes(q) || String(r.lastPacker || '').toLowerCase().includes(q))
    : modalAllRows.slice();
  if (modalSortMode === 'parcel') rows.sort((a, b) => b.parcelCount - a.parcelCount || b.agingDays - a.agingDays);
  else if (modalSortMode === 'operator') rows.sort((a, b) => String(a.lastPacker).localeCompare(String(b.lastPacker)) || b.agingDays - a.agingDays);
  else rows.sort((a, b) => b.agingDays - a.agingDays || String(a.completeTimeStr).localeCompare(String(b.completeTimeStr)));
  return rows;
}

function renderModalRows() {
  const rows = getModalVisibleRows();
  currentModalTOList = rows.map(r => r.toNo);
  document.getElementById('modalCount').innerText = rows.length === modalAllRows.length
    ? rows.length + ' TO'
    : rows.length + ' dari ' + modalAllRows.length + ' TO';
  const container = document.getElementById('modalListContainer');
  if (!rows.length) {
    container.innerHTML = '<div class="py-12 text-center text-sm text-slate-400 dark:text-slate-500"><i class="fa-regular fa-face-frown-open text-3xl mb-2 block"></i>Tidak ada TO atau operator yang cocok dengan pencarian.</div>';
    return;
  }
  container.innerHTML = rows.map((item, i) => {
    return `
    <div class="grid grid-cols-12 gap-3 px-2 py-2.5 items-center border-l-[3px] ${agingBorderClass(item.agingDays)} hover:bg-slate-50 dark:hover:bg-slate-800/70 transition">
      <div class="col-span-3 flex items-center min-w-0 gap-2">
        <span class="text-slate-400 dark:text-slate-500 text-xs w-6 shrink-0 text-right">${i + 1}</span>
        <button type="button" class="group flex items-center gap-2 min-w-0 font-mono text-sm font-semibold text-slate-800 dark:text-slate-100 hover:text-amber-600 dark:hover:text-amber-400" data-to="${escapeHtml(item.toNo)}" onclick="copyOneTO(this)" title="Klik untuk menyalin">
          <span class="truncate">${escapeHtml(item.toNo)}</span><i class="fa-regular fa-copy text-slate-300 group-hover:text-slate-500 dark:group-hover:text-slate-300 text-xs"></i>
        </button>
      </div>
      <div class="col-span-2 text-center">${toTypeBadgeHtml(item.toType)}</div>
      <div class="col-span-1 text-center font-bold text-sm text-slate-700 dark:text-slate-200">${item.parcelCount}</div>
      <div class="col-span-1 text-center"><span class="text-xs font-extrabold px-2 py-0.5 rounded-full border ${agingPillClass(item.agingDays)}">${agingLabelFromDays(item.agingDays)}</span></div>
      <div class="col-span-3 min-w-0">${modalOperatorHtml(item.lastPacker)}</div>
      <div class="col-span-2 text-right">${modalPackTimeHtml(item.completeTimeStr)}</div>
    </div>`;
  }).join('');
}

function onModalSearch(v) { modalSearchTerm = v || ''; renderModalRows(); }
function onModalSort(v) { modalSortMode = v || 'oldest'; renderModalRows(); }

function copyOneTO(btn) {
  const v = btn.getAttribute('data-to');
  if (!v) return;
  navigator.clipboard.writeText(v).then(function () {
    const ic = btn.querySelector('i');
    if (!ic) return;
    ic.className = 'fa-solid fa-check text-emerald-500 text-xs';
    setTimeout(function () { ic.className = 'fa-regular fa-copy text-slate-300 group-hover:text-slate-500 dark:group-hover:text-slate-300 text-xs'; }, 1200);
  });
}

function copyModalTable() {
  const rows = getModalVisibleRows();
  if (!rows.length) return;
  const lines = ['TO Number\tTO Type\tParcel\tAging\tOperator\tComplete Time'].concat(rows.map(r =>
    [r.toNo, r.toType, r.parcelCount, agingLabelFromDays(r.agingDays), r.lastPacker, r.completeTimeStr].join('\t')));
  navigator.clipboard.writeText(lines.join('\n')).then(function () {
    const el = document.getElementById('copyBtnTextTable');
    const o = el.innerText;
    el.innerText = 'Berhasil!';
    setTimeout(function () { el.innerText = o; }, 2000);
  });
}

function renderTOModal(titleLabel, agingType, matches) {
  const uniqueMap = new Map();
  matches.forEach(item => {
    const key = item.toNo && item.toNo !== '-' ? item.toNo : 'NO_TO';
    const itemToType = classifyToType(item);
    if (!uniqueMap.has(key)) {
      uniqueMap.set(key, {
        toNo: item.toNo,
        completeTimeStr: item.completeTimeStr,
        lastPacker: item.lastPacker,
        isHv: item.isHv,
        isLiquid: item.isLiquid,
        toType: itemToType,
        agingDays: item.agingDays || 0,
        parcelCount: 0
      });
    } else {
      const existing = uniqueMap.get(key);
      if (item.isHv) existing.isHv = true;
      if (item.isLiquid) existing.isLiquid = true;
      if (TO_TYPE_RANK[itemToType] < TO_TYPE_RANK[existing.toType]) existing.toType = itemToType;
      existing.agingDays = Math.max(existing.agingDays, item.agingDays || 0);
    }
    uniqueMap.get(key).parcelCount++;
  });

  modalAllRows = Array.from(uniqueMap.values());
  modalSearchTerm = '';
  modalSortMode = 'oldest';
  const si = document.getElementById('modalSearchInput'); if (si) si.value = '';
  const ss = document.getElementById('modalSortSelect'); if (ss) ss.value = 'oldest';

  document.getElementById('modalTitle').innerText = titleLabel;
  const repDays = { d0: 0, d1: 1, d2: 2, d3: 3, d4: 4 }[agingType];
  const pill = document.getElementById('modalAgingPill');
  pill.innerText = modalAgingTypeLabel(agingType);
  pill.className = 'text-xs font-extrabold px-2.5 py-0.5 rounded-full border ' + agingPillClass(repDays === undefined ? 5 : repDays);
  document.getElementById('modalSubtitle').innerText = matches.length.toLocaleString('id-ID') + ' parcel dalam ' + modalAllRows.length + ' nomor TO';

  const maxAge = Math.max.apply(null, modalAllRows.map(r => r.agingDays));
  const operatorCount = new Set(matches.map(m => m.lastPacker)).size;
  const typeParcels = {};
  modalAllRows.forEach(r => { typeParcels[r.toType] = (typeParcels[r.toType] || 0) + r.parcelCount; });
  const stat = (label, val) => '<div class="flex items-baseline gap-1.5"><span class="text-xs text-slate-500 dark:text-slate-400">' + label + '</span><span class="text-lg font-black text-slate-800 dark:text-slate-100">' + val + '</span></div>';
  document.getElementById('modalSummary').innerHTML =
    stat('Total TO', modalAllRows.length) + stat('Total Parcel', matches.length.toLocaleString('id-ID')) +
    stat('Operator', operatorCount) + stat('Terlama', agingLabelFromDays(maxAge)) +
    '<div class="flex items-center gap-2 flex-wrap">' + Object.keys(typeParcels).sort((a, b) => TO_TYPE_RANK[a] - TO_TYPE_RANK[b]).map(k =>
      '<span class="inline-flex items-center gap-1">' + toTypeBadgeHtml(k) + '<b class="text-sm text-slate-700 dark:text-slate-200">' + typeParcels[k] + '</b></span>').join('') + '</div>';

  renderModalRows();

  document.getElementById('toModal').classList.remove('hidden');
  document.getElementById('copyBtnTextTO').innerText = "Copy Unique TO";

  triggerFunnyAlert(agingType);
}

function showTONumbers(hubName, agingType) {
  let matches = filteredData.filter(d => d.receiverName === hubName);
  if (agingType === 'd0') matches = matches.filter(d => d.agingDays === 0);
  else if (agingType === 'd1') matches = matches.filter(d => d.agingDays === 1);
  else if (agingType === 'd2') matches = matches.filter(d => d.agingDays === 2);
  else if (agingType === 'd3') matches = matches.filter(d => d.agingDays === 3);
  else if (agingType === 'd4') matches = matches.filter(d => d.agingDays === 4);
  else if (agingType === 'd5') matches = matches.filter(d => d.agingDays >= 5);
  else if (agingType === 'd6') matches = matches.filter(d => d.agingDays === 6);
  else if (agingType === 'dMore') matches = matches.filter(d => d.agingDays > 4);

  if (matches.length === 0) return;
  renderTOModal(hubName, agingType === 'd5' ? 'd5plus' : agingType, matches);
}

function showRouteTONumbers(routeLabel, agingType) {
  const route = linehaulRoutes.find(r => r.label === routeLabel);
  if (!route) return;
  let matches = filteredData.filter(d => routeHasHub(route, d.receiverName));
  if (agingType === 'd0') matches = matches.filter(d => d.agingDays === 0);
  else if (agingType === 'd1') matches = matches.filter(d => d.agingDays === 1);
  else if (agingType === 'd2') matches = matches.filter(d => d.agingDays === 2);
  else if (agingType === 'd3') matches = matches.filter(d => d.agingDays === 3);
  else if (agingType === 'd4') matches = matches.filter(d => d.agingDays === 4);
  else if (agingType === 'd5') matches = matches.filter(d => d.agingDays >= 5);
  if (matches.length === 0) return;
  renderTOModal(routeLabel, agingType === 'd5' ? 'd5plus' : agingType, matches);
}

function showPackerTONumbers(packerName, agingType) {
  let matches = filteredData.filter(d => {
    const p = d.lastPacker && d.lastPacker !== '-' ? d.lastPacker : t('ob.packer.unassigned');
    return p === packerName;
  });

  if (agingType === 'd0') matches = matches.filter(d => d.agingDays === 0);
  else if (agingType === 'd1') matches = matches.filter(d => d.agingDays === 1);
  else if (agingType === 'd2') matches = matches.filter(d => d.agingDays === 2);
  else if (agingType === 'd3') matches = matches.filter(d => d.agingDays === 3);
  else if (agingType === 'd4') matches = matches.filter(d => d.agingDays === 4);
  else if (agingType === 'd5') matches = matches.filter(d => d.agingDays === 5);
  else if (agingType === 'd6') matches = matches.filter(d => d.agingDays >= 6);
  else if (agingType === 'dMore') matches = matches.filter(d => d.agingDays > 4);

  if (matches.length === 0) return;
  renderTOModal(packerName, agingType, matches);
}

function closeModal() { document.getElementById('toModal').classList.add('hidden'); hideFunnyAlert(); }

